// Nilad F6 — select completed orders ready for a review request.
// Requires env: REVIEW_AFTER_DAYS, STORE_URL. Input: ONE item whose json is the
// WC REST orders ARRAY (defensive: { body: [...] }).
// Keep: status=completed, date_completed older than N days, billing.email present,
// a line_item with product_id, not already asked (static sd.keys 'f6:<id>').
// Output: one item { orderId, email, firstName, productId, productName, productUrl }
//         — or [{ json: { none: true } }].
const payload = $input.first().json;
const sd = $getWorkflowStaticData('global');
sd.keys = Array.isArray(sd.keys) ? sd.keys : [];
const days = Number($env.REVIEW_AFTER_DAYS);
const thresholdMs = Number.isFinite(days) && days >= 0 ? days * 86400000 : NaN;
const orders = Array.isArray(payload) ? payload : (payload && Array.isArray(payload.body) ? payload.body : null);
if (!orders || Number.isNaN(thresholdMs)) {
  return [{ json: { none: true } }];
}
const now = Date.now();
const storeUrl = String($env.STORE_URL || '').replace(/\/+$/, '');
const out = [];
for (const o of orders) {
  if (!o || o.status !== 'completed') continue;
  const id = o.id;
  if (id === undefined || id === null) continue;
  const completed = Date.parse(o.date_completed);
  if (Number.isNaN(completed)) continue;
  if (now - completed < thresholdMs) continue;
  if (sd.keys.includes('f6:' + id)) continue;
  const b = o.billing || {};
  const email = typeof b.email === 'string' ? b.email.trim() : '';
  if (!email) continue;
  const lines = Array.isArray(o.line_items) ? o.line_items : [];
  const li = lines.find((l) => l && Number.isFinite(Number(l.product_id)) && Number(l.product_id) > 0);
  if (!li) continue;
  const productId = Number(li.product_id);
  out.push({
    json: {
      orderId: id,
      email,
      firstName: String(b.first_name || '').trim(),
      productId,
      productName: String(li.name || '').trim(),
      productUrl: storeUrl + '/?p=' + productId,
    },
  });
}
return out.length > 0 ? out : [{ json: { none: true } }];

// Nilad F6 — build the Arabic review-request email (plain text, HTML-escaped).
// Input: one candidate { orderId, email, firstName, productId, productName, productUrl }.
// Output: { orderId, email, subject, text, key } — key = f6:<orderId> for idempotency.
const j = $input.first().json;
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const name = esc(j.firstName || 'عزيزنا العميل');
const product = esc(j.productName || 'مشترياتك');
const subject = 'رأيك في «' + product + '» يهمنا';
const text = [
  'مرحباً ' + name + ',',
  '',
  'شكرًا لطلبك رقم #' + esc(j.orderId) + ' من نيلاد.',
  'آراؤك في «' + product + '» تساعدنا وتساعد زبائنًا آخرين — يُستغرق دقيقة واحدة:',
  esc(j.productUrl),
  '',
  'شكرًا جزيلًا،',
  'فريق نيلاد',
].join('\n');
return [{ json: { orderId: j.orderId, email: j.email, subject, text, key: 'f6:' + j.orderId } }];

// Nilad F6 — record 'review requested' (idempotency key f6:<orderId>, cap 500).
// Runs BEFORE the email node so the key never depends on emailSend's output shape.
// Passthrough output.
const sd = $getWorkflowStaticData('global');
sd.keys = Array.isArray(sd.keys) ? sd.keys : [];
const j = $input.first().json;
if (j.key && !sd.keys.includes(j.key)) sd.keys.push(j.key);
if (sd.keys.length > 500) sd.keys.splice(0, sd.keys.length - 500);
return [{ json: { ...j } }];
